import { Component, OnInit } from '@angular/core';
import { RouterOutlet } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { GoogleMapsModule } from '@angular/google-maps';
import { AddressService } from './address.service';

@Component({

  selector: 'app-root',
  standalone: true,
  imports: [RouterOutlet, CommonModule, ReactiveFormsModule, GoogleMapsModule],
  templateUrl: './app.component.html',
  styleUrl: './app.component.scss'
})

export class AppComponent implements OnInit {
  addressForm!: FormGroup;
  center: google.maps.LatLngLiteral = { lat: 40.7128, lng: -74.0060 }; // Default to NYC
  zoom = 10;
  savedAddresses: string[] = [];

  constructor(private fb: FormBuilder, private addressService: AddressService) {}

  ngOnInit() {

    this.addressForm = this.fb.group({

      address: ['']

    });

    this.savedAddresses = this.addressService.getAddresses();

  }

  onSubmit() {

    const address = this.addressForm.value.address;

    if (address) {

      this.addressService.saveAddress(address);

      this.savedAddresses = this.addressService.getAddresses();

      this.geocodeAndUpdateMap(address);

      this.addressForm.reset();

    }

  }

  selectAddress(address: string) {

    this.geocodeAndUpdateMap(address);

  }

  private geocodeAndUpdateMap(address: string) {

    const geocoder = new google.maps.Geocoder();

    geocoder.geocode({ address }, (results, status) => {

      if (status === google.maps.GeocoderStatus.OK && results && results[0]) {

        this.center = {

          lat: results[0].geometry.location.lat(),

          lng: results[0].geometry.location.lng()

        };

        this.zoom = 15;

      } else {

        alert('Geocode was not successful for the following reason: ' + status);

      }

    });

  }

}
<div class="container">
  <div class="form-section">
    <h2>Enter Address</h2>
    <form [formGroup]="addressForm" (ngSubmit)="onSubmit()">
      <input type="text" formControlName="address" placeholder="Enter address" required>
      <button type="submit">Save and Show Map</button>
    </form>
    <h3>Saved Addresses</h3>
    <ul class="address-list">
      <li *ngFor="let addr of savedAddresses" (click)="selectAddress(addr)" class="address-item">{{ addr }}</li>
    </ul>
  </div>
  <div class="map-section">
    <google-map [center]="center" [zoom]="zoom" width="100%" height="100%"></google-map>
  </div>
</div>
<router-outlet></router-outlet>
